-- #region model_cbf_post_thrombectomy_successful_2d
INSERT INTO model_configs (id, name, description, config) VALUES (
    'c51c1e5f-5cc1-4b77-8832-2d10cc97f234',
    'model_cbf_post_thrombectomy_successful_2d',
    'Post-mechanical thrombectomy, successful recanalization TICI 2b-3 at 2-3 days (LVO-eligible cases: Cases 7, 39 wake-up, 40 sickle cell, Cases 15 DOAC, 16 unknown onset). R_As_CaBV restored toward near-normal — mechanical clot retrieval achieves excellent recanalization. Reperfusion oedema slightly more pronounced than post-tPA (larger territory, longer ischaemic duration typical), reflected in more reduced C_SAS. C_Vent modestly reduced from mass effect of reperfusion oedema. R_SAS_Vt modestly elevated (oedema transiently impairs CSF absorption). ICP mildly elevated but CBF and CPP adequate. Good functional trajectory expected.',
