INSERT INTO model_configs (id, name, description, config) VALUES (
    'c51c1e5f-5cc1-4b77-8832-2d10cc97f238',
    'model_cbf_untreated_moderate_stroke_evolution_2d',
    'Untreated moderate ischaemic stroke at 2-3 days — evolution without reperfusion (Cases where treatment was contraindicated but stroke was moderate: Cases 12, 13, 18, 22 prior ICH, 23, 37). Established infarct core with cytotoxic oedema, then early vasogenic oedema developing by 48-72 hours. R_As_CaBV maintained high (ongoing occlusion). C_SAS moderately reduced (oedema). C_Vent reduced (mild mass effect on lateral ventricle). R_SAS_Vt elevated (moderately impaired CSF absorption from raised ICP). No haemorrhagic transformation in this model. ICP mildly-to-moderately elevated.',
